#!/usr/bin/env python3
"""Deterministic part of the documentation drift check.

Finds references in the active Markdown documents that point at nothing:

- Markdown links with a relative target whose file does not exist (anchors are ignored);
- backticked repository paths (`sync/TpSync.java`, `scripts/compose-smoke.sh`) that match no tracked file.

A backticked path is accepted when it equals a tracked path or is a path suffix of one, because the
documents write Java sources relative to `backend/src/main/java` and tests relative to
`backend/src/test/java`. Paths that are generated, private or illustrative are listed in
`IGNORED` below. Archived and investigation documents are historical and skipped.

Usage: check_doc_references.py [--root DIR] [--json]
Exit status is always 0; the report is data for the drift issue, not a gate.
"""
import argparse
import json
import re
import subprocess
import sys
from pathlib import Path

SKIPPED_PREFIXES = ("docs/archive/", "docs/investigations/", "frontend/node_modules/", "node_modules/")
# Generated by CI or the owner's machine, or deliberately not tracked.
IGNORED = (
    "quality-reports/", "coverage-kpi", "coverage/", "target/", "dist/", "node_modules/", ".env",
    "ORACLE_DEPLOYMENT_LOCAL.md", "GW2 GitHub Flow Migration.md",
)
TICKED_PATH = re.compile(r"`([A-Za-z0-9_./@-]+\.(?:java|vue|ts|mjs|js|py|yml|yaml|md|xml|json|sh|sql|properties))`")
MD_LINK = re.compile(r"\[[^\]\n]*\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")


def tracked_files(root: Path) -> list[str]:
    out = subprocess.run(["git", "ls-files"], cwd=root, capture_output=True, text=True, check=True).stdout
    return [line for line in out.splitlines() if line]


def active_documents(files: list[str]) -> list[str]:
    return [f for f in files if f.lower().endswith(".md") and not f.startswith(SKIPPED_PREFIXES)]


def path_exists(token: str, tracked: set[str], suffixes: set[str]) -> bool:
    token = token.removeprefix("./")
    return token in tracked or token in suffixes


def resolve(doc: str, target: str) -> list[str]:
    """Repository-relative path segments of `target` as written in `doc`."""
    parts: list[str] = []
    for piece in (Path(doc).parent / target).as_posix().split("/"):
        if piece == "..":
            if parts:
                parts.pop()
        elif piece not in ("", "."):
            parts.append(piece)
    return parts


def build_suffixes(tracked: set[str]) -> set[str]:
    suffixes: set[str] = set()
    for path in tracked:
        parts = path.split("/")
        for index in range(1, len(parts)):
            suffixes.add("/".join(parts[index:]))
    return suffixes


def check(root: Path) -> list[dict]:
    files = tracked_files(root)
    tracked = set(files)
    suffixes = build_suffixes(tracked)
    findings: list[dict] = []
    for doc in active_documents(files):
        text = (root / doc).read_text(encoding="utf-8", errors="replace")
        in_fence = False
        for number, line in enumerate(text.splitlines(), start=1):
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                continue
            if in_fence:
                continue
            for match in MD_LINK.finditer(line):
                target = match.group(1).split("#", 1)[0]
                if not target or re.match(r"^[a-z][a-z0-9+.-]*:", target) or target.startswith("/"):
                    continue
                parts = resolve(doc, target)
                if "/".join(parts) not in tracked and not any(t.startswith("/".join(parts) + "/") for t in tracked):
                    findings.append({"doc": doc, "line": number, "kind": "link", "reference": match.group(1)})
            for match in TICKED_PATH.finditer(line):
                token = match.group(1)
                if "/" not in token or token.startswith(("/", "~")) or any(i in token for i in IGNORED):
                    continue
                if token.startswith(("./", "../")):
                    exists = "/".join(resolve(doc, token)) in tracked
                else:
                    exists = path_exists(token, tracked, suffixes)
                if not exists:
                    findings.append({"doc": doc, "line": number, "kind": "path", "reference": token})
    return findings


def render(findings: list[dict], limit: int = 60) -> str:
    if not findings:
        return "No unresolved links or repository paths found in the active documents.\n"
    lines = [f"{len(findings)} unresolved reference(s) in the active documents:", "",
             "| Document | Line | Kind | Reference |", "|---|---:|---|---|"]
    for item in findings[:limit]:
        lines.append(f"| `{item['doc']}` | {item['line']} | {item['kind']} | `{item['reference']}` |")
    if len(findings) > limit:
        lines.append(f"| ... | | | {len(findings) - limit} more omitted |")
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=".")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()
    findings = check(Path(args.root).resolve())
    sys.stdout.write(json.dumps(findings, indent=1) + "\n" if args.json else render(findings))
    return 0


if __name__ == "__main__":
    sys.exit(main())
